def service_hero(title, description, points, option=None):
 result = hero.replace('Port St. Lucie<br>Concrete Contractor', 'Port St. Lucie<br>' + escape(title.title()))
 result = result.replace('Concrete work for your home, your property, and your next project.', escape(description))
 original = '<li>Driveway installation, repairs &amp; extensions</li><li>Foundations, concrete slabs &amp; culverts</li><li>Serving St. Lucie County &amp; Okeechobee</li>'
 result = result.replace(original, ''.join('<li>' + escape(point) + '</li>' for point in points))
 result = result.replace('Let’s talk about your project', 'Let’s talk about your ' + escape(title.lower()))
 if option:
  result = result.replace('<option>' + escape(option) + '</option>', '<option selected>' + escape(option) + '</option>')
 return result

