write('/contact/','Plan your concrete project','Prepare the details for your concrete project with RG Contracting Services.','''<section class="inner-hero"><span class="eyebrow">LET’S TALK CONCRETE</span><h1>What are you<br>building next?</h1><p>A few details help start the conversation. Tell us where you are and what you have in mind.</p></section><section class="section contact"><div><h2>Your project starts here.</h2><p>Serving Port St. Lucie, St. Lucie County, the Okeechobee area, and Vero Beach.</p><div class="notice"><strong>Call Ricardo</strong><a class="contact-phone" href="tel:+17723532541">772-353-2541 ↗</a><p>Call to discuss your project. You can also prepare and copy the details below to have ready for your conversation. This form does not send an inquiry.</p></div></div><form id="project-form"><label>Your name<input name="name" autocomplete="name" required placeholder="First and last name"></label><label>Project location<input name="location" required placeholder="City or area"></label><label>What can we help with?<select name="service">'''+''.join(f'<option value="{s[0]}">{s[1]}</option>' for s in services)+'''<option value="other">Another concrete project</option></select></label><label>Tell us about your project<textarea name="details" rows="4" required placeholder="Approximate size, current condition, and what you have in mind..."></textarea></label><button class="button" type="submit">Prepare project details <span>↗</span></button><div id="result" hidden><label>Your project summary<textarea id="summary" rows="7" readonly></textarea></label><button type="button" class="button" id="copy">Copy project details</button><p id="status" role="status"></p></div></form></section>''')
(D/'site.js').write_text('''const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));document.querySelector('nav').classList.toggle('open',!open)});const form=document.querySelector('#project-form');if(form){const service=new URLSearchParams(location.search).get('service');if([...form.service.options].some(o=>o.value===service))form.service.value=service;form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);document.querySelector('#summary').value=`Concrete project for RG Contracting Services\\nName: ${data.get('name')}\\nLocation: ${data.get('location')}\\nService: ${form.service.selectedOptions[0].text}\\nProject: ${data.get('details')}`;document.querySelector('#result').hidden=false;document.querySelector('#status').textContent='Your summary is ready. No inquiry has been sent.';});document.querySelector('#copy').addEventListener('click',async()=>{const s=document.querySelector('#summary');try{await navigator.clipboard.writeText(s.value);document.querySelector('#status').textContent='Copied. Save these details for your conversation with Ricardo.'}catch{s.focus();s.select();document.querySelector('#status').textContent='Select and copy the summary above.'}})}''')
